import java.util.*;

public class Main {
    static int[] relativeSortArray(int[] arr1, int[] arr2) {
        int n = arr1.length;
        boolean[] used = new boolean[n];
        List<Integer> result = new ArrayList<>();

        for (int v : arr2) {
            for (int i = 0; i < n; i++) {
                if (!used[i] && arr1[i] == v) {
                    result.add(arr1[i]);
                    used[i] = true;
                }
            }
        }

        List<Integer> remaining = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!used[i]) remaining.add(arr1[i]);
        }
        Collections.sort(remaining);
        result.addAll(remaining);

        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = result.get(i);
        return arr;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(relativeSortArray(new int[]{2, 3, 1, 3, 2, 4, 6, 7, 9, 2, 19}, new int[]{2, 1, 4, 3, 9, 6})));
    }
}

